{
  "name": "cursor-opencode-provider",
  "version": "0.8.5",
  "description": "Use Cursor subscription models from OpenCode via Cursor's Connect-RPC agent protocol",
  "type": "module",
  "license": "MIT",
  "author": "oakimov",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/oakimov/cursor-opencode-provider.git"
  },
  "bugs": {
    "url": "https://github.com/oakimov/cursor-opencode-provider/issues"
  },
  "homepage": "https://github.com/oakimov/cursor-opencode-provider#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "cursor",
    "ai-sdk",
    "provider",
    "plugin"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./plugin": {
      "types": "./dist/plugin.d.ts",
      "import": "./dist/plugin.js"
    },
    "./plugin/v2": {
      "types": "./dist/plugin-v2.d.ts",
      "import": "./dist/plugin-v2.js"
    },
    "./plugin/opencode2": {
      "types": "./dist/plugin-opencode2.d.ts",
      "import": "./dist/plugin-opencode2.js"
    },
    "./server": {
      "types": "./dist/plugin-opencode2.d.ts",
      "import": "./dist/plugin-opencode2.js"
    },
    "./errors": {
      "types": "./dist/errors.d.ts",
      "import": "./dist/errors.js"
    },
    "./models": {
      "types": "./dist/models.d.ts",
      "import": "./dist/models.js"
    },
    "./pricing": {
      "types": "./dist/pricing.d.ts",
      "import": "./dist/pricing.js"
    },
    "./auth": {
      "types": "./dist/auth.d.ts",
      "import": "./dist/auth.js"
    },
    "./image-save": {
      "types": "./dist/image-save.d.ts",
      "import": "./dist/image-save.js"
    }
  },
  "files": [
    "dist",
    "LICENSE",
    "DISCLAIMER.md",
    "SECURITY.md",
    "README.md",
    "CHANGELOG.md"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit && tsc --noEmit -p tsconfig.test.json",
    "test": "bun test",
    "test:coverage": "bun test --coverage --coverage-reporter=lcov && bun scripts/strip-copied-coverage.ts",
    "test:node-http2": "bun run build && node test/node-http2-cleanup.mjs && node test/node-http2-drain.mjs && node test/node-http2-session-memory.mjs",
    "test:watch": "bun test --watch",
    "generate:pricing": "bun run scripts/generate-cursor-pricing.ts",
    "generate:pricing:check": "bun run scripts/generate-cursor-pricing.ts -- --check",
    "check:pricing": "bun run scripts/check-cursor-pricing-coverage.ts",
    "prepublishOnly": "bun run generate:pricing && bun run build"
  },
  "dependencies": {
    "@ai-sdk/provider": "3.0.15",
    "protobufjs": "^7.6.5"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.17.13"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.16",
    "@tsconfig/node22": "^22.0.5",
    "@types/bun": "^1.3.0",
    "@types/node": "^22.20.1",
    "typescript": "^5.9.3"
  }
}
